// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.26;

import {RoundFloorVault} from "./RoundFloorVault.sol";
import {PathFeeConverter} from "./PathFeeConverter.sol";
import {TreasuryBurnEscrow} from "./TreasuryBurnEscrow.sol";
import {TaxFeeSink} from "../v3/TaxFeeSink.sol";

/// @title WinkModeLauncherV4(v3 + TickerRegistry 查重;其余逐字节同 v3)—— 「BLINK 配对税率托底」发射模式(wink mode)
///
/// WINK 这单谈出来的结构,沉淀成一种可复用的发射模式:
///   股票币底池 + 双向 3.3% 池级税(0.3% 平台层 + 3.0% 机制层)
///   + 税→BLINK→轮次托底金库 + 兑换销毁权重分红 + 项目方金库只烧不跑托管。
///
/// **经济结构焊死在这份字节码里** —— 费率、分账比例、平台收款地址、接线拓扑,
/// 发射方一个都改不了;能填的只有身份参数(名字/符号/计价币/自家收款地址/盐)。
/// 所以「用这个模式发射」本身就是合规声明:发出来的每一枚,结构与 WINK 逐字节同构。
///
/// 一笔交易原子出全套(轨道同 SILSQ,二号演练盘已真金走通):
///   预测 asset → 部署 RoundFloorVault / PathFeeConverter / TreasuryBurnEscrow /
///   平台 TaxFeeSink → airlock.create(建池挂税、受益人三方、治理钥匙烧掉)→ 断言接线。
/// 原子性消灭无税抢跑窗口;任何人可调(发射方自己拿钱包发,不必信平台代火)。
interface IAirlockWM {
    function create(CreateParamsWM calldata) external returns (address, address, address, address, address);
}

interface ITokenFactoryImplWM {
    function IMPLEMENTATION() external view returns (address);
}

interface IPoolInitStateWM {
    function getState(address asset)
        external view returns (address, uint256, address, bytes memory, uint8, address, address, uint24, int24, address, int24);
}

interface IRehypeInfoWM {
    function getPoolInfo(bytes32 poolId) external view returns (address, address, address);
}

struct CurveWM { int24 tickLower; int24 tickUpper; uint16 numPositions; uint256 shares; }
struct BenWM { address beneficiary; uint96 shares; }
struct InitDataWM {
    uint24 fee; int24 tickSpacing; int24 farTick;
    CurveWM[] curves; BenWM[] beneficiaries;
    address dopplerHook; bytes onInit; bytes onGrad;
}
struct CreateParamsWM {
    uint256 initialSupply; uint256 numTokensToSell; address numeraire;
    address tokenFactory; bytes tokenFactoryData;
    address governanceFactory; bytes governanceFactoryData;
    address poolInitializer; bytes poolInitializerData;
    address liquidityMigrator; bytes liquidityMigratorData;
    address integrator; bytes32 salt;
}

interface ITickerRegistryW {
    function claim(string calldata symbol, address token) external returns (bytes32);
}

contract WinkModeLauncherV4 {
    /// @notice 符号唯一性注册表(v4 新增,2026-09-12;对标 LONG ticker 锁)。immutable,焊死。
    ITickerRegistryW public immutable tickerRegistry;

    constructor(address tickerRegistry_) {
        tickerRegistry = ITickerRegistryW(tickerRegistry_);
    }

    error PredictionMismatch();
    error WiringBroken();
    error BadParams();

    event WinkModeLaunched(
        address indexed asset,
        address indexed creator,
        address vault,
        address converter,
        address escrow,
        address platformSink
    );

    // ── 轨道常量(与 SILSQ / 二号演练盘同源)
    address public constant AIRLOCK       = 0xeb7C034704eF8Dcd2D32324c1545f62fB4aD0862;
    address public constant TOKEN_FACTORY = 0x1B37D3a72082029c44B35B604Ea473617580b69a;
    address public constant GOV_FACTORY   = 0xdb036746D65DD52126b1915f1AdF555e6C5237Cf;
    address public constant POOL_INIT     = 0x4e3468951D49f2EEa976eD0D6e75fFCb44a9a544;
    address public constant LIQ_MIGRATOR  = 0xba2F330EDb16cD8056f5988d8CE19BbC63475A0e;
    address public constant REHYPE_HOOK   = 0x6f02324d20CC679d0E585290CAa6b16baCbC0F77;
    address public constant PROTOCOL_BEN  = 0x21E2ce70511e4FE542a97708e89520471DAa7A66;
    address public constant OUR_BEN       = 0xefB0b09c66CB66943c1D5Ce796f5f577070de46e;
    /// @notice 平台份额的最终去向(社区金库钱包,2026-09-09 商务定稿)。
    address public constant PLATFORM_WALLET = 0xbd413EA580C40AC39C559c6010a3E771E9cC1845;
    address public constant DEAD          = 0x000000000000000000000000000000000000dEaD;
    address public constant WETH          = 0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73;
    address public constant BLINK         = 0x7b630F080807DF83908b4aDE46BA6396EE66b098;
    address public constant ROUTER        = 0xCaf681a66D020601342297493863E78C959E5cb2;

    // ── wink mode 的经济结构(不可配置 —— 这就是「模式」)
    uint24  public constant DYNAMIC_FEE  = 0x800000;
    int24   public constant TICK_SPACING = 8;
    int24   public constant FAR_TICK     = 887256;
    int24   public constant CURVE_KNEE   = -51296; // 主曲线上沿(与 SILSQ 同);startTick 必须在它下方
    uint24  public constant POOL_FEE     = 3_000;   // 第一层 0.3%:平台份额所在层
    uint24  public constant START_FEE    = 640_000; // 开盘防狙击 80%,15 秒衰减
    uint24  public constant END_FEE      = 24_000;  // 第二层稳态 3.0% → 机制金库
    uint32  public constant DECAY_SEC    = 15;
    uint96  public constant PROTOCOL_WAD = 5e16;  // Doppler 强制 5%
    uint96  public constant PLATFORM_WAD = 95e16; // 其余全归平台 —— 0.3% 层是平台收入,项目方不分(老板 09-10 定死)

    struct ModeParams {
        string  name;
        string  symbol;
        string  uri;
        address numeraire;          // 底池计价币(WINK 用 NVDA)
        /// 开盘 tick(决定开盘 FDV;v3 起项目方可定 —— WINK 方 09-10 要求)。
        /// 必须是 8 的倍数、落在 (-300000, -51296):上界=主曲线拐点,下界=荒谬估值护栏。
        int24   startTick;
        address treasuryBeneficiary; // 托管产出的唯一去向(项目方自己的地址)
        address treasuryOperator;   // 托管兑换销毁的触发者
        uint256 maxNumerairePerSync; // 转换器单次限额(0=不限;正式盘按 $2000 名义额折枚)
        bytes32 salt;               // 挖好的盐(如 dbdb 尾号)
    }

    function predictAsset(bytes32 salt) public view returns (address) {
        address impl = ITokenFactoryImplWM(TOKEN_FACTORY).IMPLEMENTATION();
        bytes32 h = keccak256(abi.encodePacked(
            hex"602c3d8160093d39f3_3d3d3d3d363d3d37363d73", impl, hex"5af43d3d93803e602a57fd5bf3"
        ));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), TOKEN_FACTORY, salt, h)))));
    }

    function launch(ModeParams calldata p)
        external
        returns (address asset, address vault, address converter, address escrow, address platformSink)
    {
        if (
            p.numeraire == address(0) || p.numeraire.code.length == 0
            || p.treasuryBeneficiary == address(0) || p.treasuryOperator == address(0)
            || p.startTick % TICK_SPACING != 0 || p.startTick >= CURVE_KNEE || p.startTick <= -300_000
        ) revert BadParams();

        asset = predictAsset(p.salt);

        // 符号唯一性:保护期内同名符号在这里整笔回滚 —— 在部署四件套之前失败,最省 gas。
        tickerRegistry.claim(p.symbol, asset);

        // ── 机制四件套,全部指向预测出的 asset
        vault = address(new RoundFloorVault(asset, BLINK));
        converter = address(new PathFeeConverter(
            asset,
            p.numeraire,
            BLINK,
            ROUTER,
            vault,
            abi.encodePacked(asset, uint24(10_000), BLINK), // asset 腿正常永不入账(税在 hook 内全转计价币)
            abi.encodePacked(p.numeraire, uint24(500), WETH, uint24(10_000), BLINK),
            0,
            p.maxNumerairePerSync
        ));
        escrow = address(new TreasuryBurnEscrow(vault, asset, p.treasuryBeneficiary, p.treasuryOperator));
        platformSink = address(new TaxFeeSink(POOL_INIT, asset, p.numeraire, PLATFORM_WALLET));

        // ── 建池挂税(受益人升序;两侧税全转计价币打给转换器)
        CurveWM[] memory curves = new CurveWM[](2);
        curves[0] = CurveWM(p.startTick, CURVE_KNEE, 1, 991e15);
        curves[1] = CurveWM(CURVE_KNEE, 887264, 1, 9e15);

        InitDataWM memory d = InitDataWM({
            fee: POOL_FEE,
            tickSpacing: TICK_SPACING,
            farTick: FAR_TICK,
            curves: curves,
            beneficiaries: _sortedBens(platformSink),
            dopplerHook: REHYPE_HOOK,
            onInit: abi.encode(
                p.numeraire, converter,
                START_FEE, END_FEE, DECAY_SEC, uint32(0), uint8(0),
                uint256(0), uint256(1e18), uint256(0), uint256(0),
                uint256(0), uint256(1e18), uint256(0), uint256(0)
            ),
            onGrad: bytes("")
        });

        (address created,,,,) = IAirlockWM(AIRLOCK).create(CreateParamsWM({
            initialSupply: 1e27,
            numTokensToSell: 1e27,
            numeraire: p.numeraire,
            tokenFactory: TOKEN_FACTORY,
            tokenFactoryData: abi.encode(
                p.name, p.symbol,
                new bytes32[](0), new address[](0), new uint256[](0), new uint256[](0),
                p.uri, uint256(0), uint48(0), address(0), new address[](0)
            ),
            governanceFactory: GOV_FACTORY,
            governanceFactoryData: abi.encode(DEAD), // 治理钥匙烧掉:发完即终态
            poolInitializer: POOL_INIT,
            poolInitializerData: abi.encode(d),
            liquidityMigrator: LIQ_MIGRATOR,
            liquidityMigratorData: bytes(""),
            integrator: OUR_BEN,
            salt: p.salt
        }));
        if (created != asset) revert PredictionMismatch();

        // ── 发射后自检:税真的指向转换器 + 治理钥匙真的烧了(不对整笔回滚)
        (address c0, address c1) = asset < p.numeraire ? (asset, p.numeraire) : (p.numeraire, asset);
        bytes32 poolId = keccak256(abi.encode(c0, c1, DYNAMIC_FEE, TICK_SPACING, POOL_INIT));
        (,, address dst) = IRehypeInfoWM(REHYPE_HOOK).getPoolInfo(poolId);
        if (dst != converter) revert WiringBroken();
        (,, address hook,,,,,,,,) = IPoolInitStateWM(POOL_INIT).getState(asset);
        if (hook != REHYPE_HOOK) revert WiringBroken();

        emit WinkModeLaunched(asset, msg.sender, vault, converter, escrow, platformSink);
    }

    /// @dev Doppler 要求受益人按地址升序;两个受益人,比一下就行。
    function _sortedBens(address platformSink) internal pure returns (BenWM[] memory out) {
        out = new BenWM[](2);
        (address a, address b) = PROTOCOL_BEN < platformSink ? (PROTOCOL_BEN, platformSink) : (platformSink, PROTOCOL_BEN);
        out[0] = BenWM(a, a == PROTOCOL_BEN ? PROTOCOL_WAD : PLATFORM_WAD);
        out[1] = BenWM(b, b == PROTOCOL_BEN ? PROTOCOL_WAD : PLATFORM_WAD);
    }
}

