// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.26;

/// @title RoundFloorVault(即对接书里的 BlinkReserveAndBurnRewards)
/// @notice WINK 官方对接说明书 V3.0 的逐条实现:轮次托底 + 兑换销毁 + 销毁权重分红。
///
/// 规格来源(2026-09-09,杨仔 docx §3-§9 + TG 补充),逐条对照:
///   - 每轮额度 1 亿 WINK;累计兑换销毁满额即 RoundCompleted,下一轮重置(§7)
///   - 兑换价:blinkOut = 本轮销毁量 × reserveBalance ÷ roundRemaining —— 同轮内无新入账时
///     单价不变(数学:兑换后分子分母同比例缩减);新税入账则单价上升(§7)
///   - 单笔跨轮:按轮切分、各轮独立结算(§7"单笔销毁超过本轮剩余额度")
///   - 空储备仍可销毁:到账 0,但销毁有效、权重增加、轮次推进,不回滚(§2 边界声明、§7)
///   - 分账按「实际到账 X」:totalBurnShares==0 → 100% 托底;>0 → floor(X×2/3) 托底,
///     余数进分红负债(§3);无人销毁阶段进托底的钱**不追溯补发**(§6)
///   - 权重 = 累计经 redeem 销毁量,领奖不减权重;新权重不吃旧分红(§6)
///   - 入账双口径:deposit(approve+拉取)或 直接转账+sync,任何人可 poke(§9)
///   - setShare 空实现,兼容 FlapTaxTokenV3 的分红回调口径(§9)
///   - 构造参数只有 projectToken 与 blink,均 immutable;没有提取、没有管理员、没有升级(§9)
contract RoundFloorVault {
    error ZeroAmount();
    error BelowMinRedeem();
    error NothingToClaim();
    error PullFailed();
    error PayFailed();
    error Reentrant();

    event Deposited(address indexed from, uint256 amount);
    event Synced(uint256 toReserve, uint256 toRewards);
    event Redeemed(address indexed who, uint256 winkBurned, uint256 blinkOut, uint256 roundAfter);
    event RoundCompleted(uint256 indexed round);
    event RewardsClaimed(address indexed who, address indexed to, uint256 amount);

    uint256 public constant ROUND_QUOTA = 100_000_000e18; // 1 亿 WINK / 轮(§3)
    uint256 public constant MIN_REDEEM = 10_000e18; // 最低有效销毁(09-09 项目方补充确认)
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 internal constant MAG = 2 ** 128;

    IERC20R public immutable projectToken; // WINK
    IERC20R public immutable blink;

    uint256 public reserveBalance; // 托底储备(BLINK)
    uint256 public rewardLiability; // 分红负债(BLINK,待领取总额)
    uint256 public totalBurnShares; // 累计销毁权重总量
    uint256 public currentRound = 1;
    uint256 public roundRemaining = ROUND_QUOTA;
    uint256 public magRewardPerShare;

    mapping(address => uint256) public burnSharesOf;
    mapping(address => uint256) public claimedMagOf;

    uint256 private _lock = 1;

    modifier nonReentrant() {
        if (_lock != 1) revert Reentrant();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(address projectToken_, address blink_) {
        projectToken = IERC20R(projectToken_);
        blink = IERC20R(blink_);
    }

    // ------------------------------------------------------------ 入账(§3 分流、§9 双口径)
    function sync() public {
        uint256 bal = blink.balanceOf(address(this));
        uint256 tracked = reserveBalance + rewardLiability;
        if (bal <= tracked) return;
        uint256 fresh = bal - tracked;

        if (totalBurnShares == 0) {
            reserveBalance += fresh; // 无人销毁:100% 托底,不产生分红负债
            emit Synced(fresh, 0);
        } else {
            uint256 toReserve = (fresh * 2) / 3; // 规格原文:floor(X × 2 / 3)
            uint256 toRewards = fresh - toReserve;
            reserveBalance += toReserve;
            rewardLiability += toRewards;
            magRewardPerShare += (toRewards * MAG) / totalBurnShares;
            emit Synced(toReserve, toRewards);
        }
    }

    /// @notice TaxProcessor 口径:先 approve BLINK,再由金库拉取并按实际到账分账。
    function deposit(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        if (!blink.transferFrom(msg.sender, address(this), amount)) revert PullFailed();
        emit Deposited(msg.sender, amount);
        sync();
    }

    // ------------------------------------------------------------ 唯一销毁入口(§5、§7)
    /// @notice 兑换销毁:WINK 进 DEAD,按当轮公式领取可兑 BLINK,并永久计入销毁权重。
    ///         跨轮自动切分;空储备到账为 0 但销毁与权重照常。
    function redeem(uint256 amount, address to) external nonReentrant returns (uint256 blinkOut) {
        if (amount < MIN_REDEEM) revert BelowMinRedeem();
        if (to == address(0)) to = msg.sender;
        sync();

        // 先把领取水位对齐到当前累加器:新权重不吃旧分红(§6)
        claimedMagOf[msg.sender] += amount * magRewardPerShare;
        burnSharesOf[msg.sender] += amount;
        totalBurnShares += amount;

        uint256 left = amount;
        while (left > 0) {
            uint256 take = left < roundRemaining ? left : roundRemaining;
            uint256 slice = roundRemaining == 0 ? 0 : (take * reserveBalance) / roundRemaining;
            reserveBalance -= slice;
            roundRemaining -= take;
            blinkOut += slice;
            left -= take;
            if (roundRemaining == 0) {
                emit RoundCompleted(currentRound);
                currentRound += 1;
                roundRemaining = ROUND_QUOTA;
            }
        }

        if (!projectToken.transferFrom(msg.sender, DEAD, amount)) revert PullFailed();
        if (blinkOut > 0 && !blink.transfer(to, blinkOut)) revert PayFailed();
        emit Redeemed(msg.sender, amount, blinkOut, currentRound);
    }

    // ------------------------------------------------------------ 分红(§6)
    function rewardsOwed(address who) public view returns (uint256) {
        uint256 gross = burnSharesOf[who] * magRewardPerShare;
        uint256 used = claimedMagOf[who];
        return gross <= used ? 0 : (gross - used) / MAG;
    }

    function claim(address to) external nonReentrant returns (uint256 amount) {
        if (to == address(0)) to = msg.sender;
        sync();
        amount = rewardsOwed(msg.sender);
        if (amount == 0) revert NothingToClaim();
        claimedMagOf[msg.sender] += amount * MAG;
        rewardLiability -= amount;
        if (!blink.transfer(to, amount)) revert PayFailed();
        emit RewardsClaimed(msg.sender, to, amount);
    }

    // ------------------------------------------------------------ 兼容与视图
    /// @notice FlapTaxTokenV3 的分红回调兼容位。本机制不按持仓分红 —— 空操作(§9)。
    function setShare(address, uint256) external {}

    /// @notice 当轮单枚 WINK 的托底价(×1e18)。
    function floorPriceX18() external view returns (uint256) {
        return roundRemaining == 0 ? 0 : (reserveBalance * 1e18) / roundRemaining;
    }
}

interface IERC20R {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

