// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.26;

/// @title PathFeeConverter —— 多跳费流转换器(WINK/NVDA 场景;FeeConverter 的路径泛化版)
/// @notice WINK 配对的是 NVDA,而托底资产是 BLINK —— 费的两侧(WINK、NVDA)都不是
///         BLINK,单跳池换不动,需要多跳路径:
///           WINK  → (WINK/NVDA 池) → NVDA → (NVDA/WETH) → WETH → (WETH/BLINK) → BLINK
///           NVDA  → (NVDA/WETH)    → WETH → (WETH/BLINK) → BLINK
///         两条 V3 `exactInput` path 在**构造时写死,没有 setter** —— 路由和去向
///         一经部署对谁都不可改(与 FeeConverter/TaxFeeSink 同门纪律)。
///
/// sync() 无许可:换币、全额转给金库、poke 金库入账。谁调都一样,调用者零好处。
/// 滑点防护 = 单次限额(maxAssetPerSync / maxNumerairePerSync,构造时定死):
/// 一次 sync 最多只换这么多,余量留给下一次 poke —— 单笔被夹的最大损失被
/// 限额钉死,守护进程高频小批清余量。minOut 仍为 0(限额已经界定了最坏情况,
/// 且钱只会"少换点 BLINK 进金库",本金没有第三方出口);限额传 0 = 不设限。
interface IERC20P {
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function transfer(address, uint256) external returns (bool);
}

interface ISwapRouterPath {
    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    function exactInput(ExactInputParams calldata) external payable returns (uint256);
}

interface IVaultSyncP {
    function sync() external;
}

contract PathFeeConverter {
    IERC20P public immutable asset; // WINK
    IERC20P public immutable numeraire; // NVDA
    IERC20P public immutable blink;
    ISwapRouterPath public immutable router;
    address public immutable vault;

    uint256 public immutable maxAssetPerSync; // 单次最多换多少 asset(0=不限)
    uint256 public immutable maxNumerairePerSync; // 单次最多换多少 numeraire(0=不限)

    bytes public assetPath; // WINK→…→BLINK,构造后不可改(无 setter)
    bytes public numerairePath; // NVDA→…→BLINK,同上

    event Converted(uint256 assetIn, uint256 numeraireIn, uint256 blinkForwarded);

    constructor(
        address asset_,
        address numeraire_,
        address blink_,
        address router_,
        address vault_,
        bytes memory assetPath_,
        bytes memory numerairePath_,
        uint256 maxAssetPerSync_,
        uint256 maxNumerairePerSync_
    ) {
        asset = IERC20P(asset_);
        numeraire = IERC20P(numeraire_);
        blink = IERC20P(blink_);
        router = ISwapRouterPath(router_);
        vault = vault_;
        assetPath = assetPath_;
        numerairePath = numerairePath_;
        maxAssetPerSync = maxAssetPerSync_;
        maxNumerairePerSync = maxNumerairePerSync_;
    }

    function _capped(uint256 bal, uint256 cap) internal pure returns (uint256) {
        return cap == 0 || bal < cap ? bal : cap;
    }

    /// @dev 每腿独立尽力而为:一腿换不动(路径上的池子没流动性、或有人恶意捐入
    ///      根本没有池子的粉尘)绝不能堵死另一腿 —— 路径不可改,一个 revert 腿
    ///      就是永久 DoS。失败的腿余额原地等,路径恢复后任何人再 poke 即补清。
    function _trySwap(IERC20P token, bytes memory path, uint256 amountIn) internal {
        token.approve(address(router), amountIn);
        (bool ok,) = address(router).call(
            abi.encodeCall(ISwapRouterPath.exactInput, (ISwapRouterPath.ExactInputParams(path, address(this), amountIn, 0)))
        );
        ok; // 显式忽略:失败=这腿这次不换,钱还在原地
    }

    function sync() external {
        uint256 a = _capped(asset.balanceOf(address(this)), maxAssetPerSync);
        if (a > 0) _trySwap(asset, assetPath, a);
        uint256 n = _capped(numeraire.balanceOf(address(this)), maxNumerairePerSync);
        if (n > 0) _trySwap(numeraire, numerairePath, n);
        uint256 b = blink.balanceOf(address(this));
        if (b > 0) {
            require(blink.transfer(vault, b), "forward failed");
            IVaultSyncP(vault).sync();
        }
        emit Converted(a, n, b);
    }
}

