// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.26;

/// @title TreasuryBurnEscrow —— 项目方社区金库的"只能烧不能跑"托管
/// @notice WINK 方想把他们社区金库的兑换权利放在我们这边。我们不做保管人 ——
///         **托管的是规则,不是钥匙**:金库 WINK 转进本合约后,唯一出口是
///         RoundFloorVault.redeem(兑换销毁),所有产出(兑到的 BLINK、后续分红)
///         焊死打给部署时写定的 beneficiary(他们自己的收款地址)。
///
///         谁都得不到第二条路:没有 withdraw、没有改地址、没有管理员、没有升级。
///         我们平台拿到的只是一个触发权(operator 决定何时烧多少),对钱本身
///         没有任何取向权 —— 社区看合约就知道"项目方金库跑不了,我们也拿不走"。
///
/// 权力形状:
///   - redeem:仅 operator(触发时点与数量是运营决策,不宜无许可 —— 否则任何人
///     都能在最差价位替他们清库存);产出直达 beneficiary,operator 摸不到钱
///   - claim:无许可,分红同样直达 beneficiary(keeper 可代劳)
///   - operator 丢钥匙的后果:WINK 停在合约里继续等(仍然只能烧),分红仍可被
///     任何人替 beneficiary 领 —— 没有资金安全问题,只有操作停摆
interface IRoundVaultE {
    function redeem(uint256 amount, address to) external returns (uint256);
    function claim(address to) external returns (uint256);
}

interface IERC20E {
    function approve(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

contract TreasuryBurnEscrow {
    error NotOperator();

    event TreasuryRedeemed(uint256 winkBurned, uint256 blinkToBeneficiary);
    event TreasuryClaimed(uint256 blinkToBeneficiary);

    IRoundVaultE public immutable vault;
    IERC20E public immutable wink;
    /// @notice 一切产出的唯一去向(项目方自己的地址)。immutable,永久。
    address public immutable beneficiary;
    /// @notice 唯一的触发者(兑换销毁的时点与数量)。immutable;只有触发权,没有取向权。
    address public immutable operator;

    constructor(address vault_, address wink_, address beneficiary_, address operator_) {
        vault = IRoundVaultE(vault_);
        wink = IERC20E(wink_);
        beneficiary = beneficiary_;
        operator = operator_;
    }

    /// @notice 把托管的 WINK 兑换销毁。产出 BLINK 直达 beneficiary,权重记在本合约名下。
    function redeem(uint256 amount) external returns (uint256 blinkOut) {
        if (msg.sender != operator) revert NotOperator();
        wink.approve(address(vault), amount);
        blinkOut = vault.redeem(amount, beneficiary);
        emit TreasuryRedeemed(amount, blinkOut);
    }

    /// @notice 领本合约权重应得的分红,直达 beneficiary。无需许可,谁替领都一样。
    function claim() external returns (uint256 amount) {
        amount = vault.claim(beneficiary);
        emit TreasuryClaimed(amount);
    }
}

