// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.26;

/// @title TaxFeeSink —— Doppler 轨道 3% 交易税的受益人(WINK 二期;BLINK 配对税库模式)
///
/// 二期要的是**真·池级交易税**:双向 3%,由 Doppler/Rehype 在 swap 里按输出侧取,
/// 与转账无关(V3 转账税那条死路的正解,fork 与主网双重实证 —— SILSQ 现网跑的
/// 就是同一条轨道、同一个 3% 档)。
///
/// 这个合约解决轨道的最后一公里:**Rehype 的费不会自动到账 —— 受益人必须自己
/// 发交易调 `collectFees(poolId)`,而合约只付给 `msg.sender`。**
/// 所以受益人不能是一个哑地址,得是一个能自己领、领完自动转发的合约。
///
/// 权力形状(和 FloorVault / BuybackVault 同门):
///   - `collect()` **无需许可**:谁都能触发,钱只会流向出生时写死的 converter;
///     调用者一分好处没有,只付 gas(对齐 LpLock.claimFees 的老规矩);
///   - **没有 `updateBeneficiary`,没有提取,没有管理员,没有升级** ——
///     Doppler 的受益人份额本来可以被受益人自己转走(第 8 轮审计点名过的风险),
///     而本合约把这条路**从字节码里删掉了**:费路由一经发射,对谁都是永久的;
///   - 两种币(asset 侧与 numeraire 侧)一并转发,converter 会把 asset 换成 BLINK
///     再连同 BLINK 侧一起注入 FloorVault(托底 + 2:1 + 销毁权重分红)。
interface IPoolInitCollect {
    function collectFees(bytes32 poolId) external returns (uint128 fees0, uint128 fees1);
}

interface IERC20S {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

interface IConverterSync {
    function sync() external;
}

contract TaxFeeSink {
    error NothingCollected();
    error ForwardFailed(address token);

    event Collected(bytes32 indexed poolId, uint128 fees0, uint128 fees1);
    event Forwarded(uint256 assetAmt, uint256 numeraireAmt);

    /// @notice Doppler 的池初始化器(领费入口所在)。
    IPoolInitCollect public immutable poolInit;
    /// @notice 这枚币本身(费的 asset 侧)。
    IERC20S public immutable asset;
    /// @notice 计价资产 = BLINK(费的 numeraire 侧)。
    IERC20S public immutable numeraire;
    /// @notice 费的唯一去处:换币并注入 FloorVault 的转换器。**immutable,永久。**
    address public immutable converter;

    constructor(address poolInit_, address asset_, address numeraire_, address converter_) {
        poolInit = IPoolInitCollect(poolInit_);
        asset = IERC20S(asset_);
        numeraire = IERC20S(numeraire_);
        converter = converter_;
    }

    /// @notice 领这个池子累积的交易税并全额转发。无需许可。
    /// @dev 领费可能失败(Doppler 侧的已知敞口:毕业开关 + 极值价格会让 collectFees 永久失效)。
    ///      失败就 revert,不吞 —— 这个函数没有"部分成功"的语义,调用者重试即可。
    function collect(bytes32 poolId) external returns (uint256 a, uint256 n) {
        (uint128 f0, uint128 f1) = poolInit.collectFees(poolId);
        emit Collected(poolId, f0, f1);
        (a, n) = _forward();
        if (a == 0 && n == 0) revert NothingCollected();
    }

    /// @notice 只转发已经躺在本合约里的费(有人直接转进来、或上次转发失败时用)。无需许可。
    function forward() external returns (uint256 a, uint256 n) {
        (a, n) = _forward();
        if (a == 0 && n == 0) revert NothingCollected();
    }

    function _forward() internal returns (uint256 a, uint256 n) {
        a = asset.balanceOf(address(this));
        if (a > 0 && !asset.transfer(converter, a)) revert ForwardFailed(address(asset));
        n = numeraire.balanceOf(address(this));
        if (n > 0 && !numeraire.transfer(converter, n)) revert ForwardFailed(address(numeraire));
        if (a > 0 || n > 0) {
            // 转换器把 asset 换成 BLINK 并注入金库。失败不回滚本次转发 ——
            // 钱已经在转换器里,任何人可以再 poke 它一次(和 LpLock 对 sync 的处理同理)。
            (bool ok,) = converter.call(abi.encodeWithSelector(IConverterSync.sync.selector));
            ok; // 显式忽略:钱的去向已确定,sync 只是提前记账
            emit Forwarded(a, n);
        }
    }
}
